<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Building2, MessageCircle, ShieldCheck, UserRound } from '@lucide/vue'
import { api } from '../api'
const settings = ref<any>(null); const loading = ref(true); const saving = ref(''); const error = ref(''); const success = ref('')
const personal = reactive({ display_name: '', phone_number_id: '', business_account_id: '', access_token: '', graph_version: 'v25.0' })
const company = reactive({ display_name: '', phone_number_id: '', business_account_id: '', access_token: '', graph_version: 'v25.0' })
const canManageCompany = computed(() => Boolean(settings.value?.can_manage_company_account))
function fill(target: any, account: any) { target.display_name = account?.display_name || ''; target.phone_number_id = account?.phone_number_id || ''; target.business_account_id = account?.business_account_id || ''; target.access_token = ''; target.graph_version = account?.graph_version || 'v25.0' }
async function load() { loading.value = true; try { const { data } = await api.get('/whatsapp/settings'); settings.value = data; fill(personal, data.personal_account); fill(company, data.company_account) } catch (exception: any) { error.value = exception.response?.data?.message || 'WhatsApp settings could not be loaded.' } finally { loading.value = false } }
async function save(scope: 'personal' | 'company') { saving.value = scope; error.value = ''; success.value = ''; const source = scope === 'personal' ? personal : company; const payload: any = { ...source }; if (!payload.access_token) delete payload.access_token; try { await api.put(`/whatsapp/accounts/${scope}`, payload); success.value = `${scope === 'personal' ? 'Personal' : 'Company'} WhatsApp Business account saved.`; await load() } catch (exception: any) { error.value = Object.values(exception.response?.data?.errors || { error: [exception.response?.data?.message || 'The account could not be saved.'] }).flat().join(' ') } finally { saving.value = '' } }
async function disconnect(scope: 'personal' | 'company') { if (!window.confirm(`Disconnect the ${scope} WhatsApp Business account? Existing message history will be kept.`)) return; saving.value = scope; try { await api.delete(`/whatsapp/accounts/${scope}`); success.value = 'WhatsApp Business account disconnected.'; await load() } catch (exception: any) { error.value = exception.response?.data?.message || 'The account could not be disconnected.' } finally { saving.value = '' } }
async function saveTemplate(template: any) { saving.value = `template-${template.id}`; error.value = ''; try { await api.patch(`/whatsapp/templates/${template.id}`, { meta_template_name: template.meta_template_name, language_code: template.language_code, is_active: template.is_active }); success.value = `${template.name} mapping saved.` } catch (exception: any) { error.value = Object.values(exception.response?.data?.errors || { error: [exception.response?.data?.message || 'The template mapping could not be saved.'] }).flat().join(' ') } finally { saving.value = '' } }
onMounted(load)
</script>
<template>
  <div class="whatsapp-settings-page"><header class="page-heading"><div><span class="eyebrow">META INTEGRATION</span><h1>WhatsApp Business</h1><p>Connect a personal business number or use the company fallback to send approved templates to leads.</p></div><span class="whatsapp-driver"><ShieldCheck :size="16" />{{ settings?.driver === 'meta' ? 'Meta delivery enabled' : 'Safe log mode' }}</span></header>
    <div v-if="error" class="detail-alert">{{ error }}<button @click="error = ''">Dismiss</button></div><div v-if="success" class="team-success">{{ success }}</div><div v-if="loading" class="panel whatsapp-loading">Loading integration settings…</div>
    <template v-else><section class="whatsapp-account-grid"><form class="panel whatsapp-account-card" @submit.prevent="save('personal')"><header><UserRound /><div><h2>My business account</h2><p>Used first for messages you send in this company.</p></div></header><label>Display name<input v-model="personal.display_name" required maxlength="120"></label><label>Phone number ID<input v-model="personal.phone_number_id" required maxlength="80"></label><label>Business account ID<input v-model="personal.business_account_id" maxlength="80"></label><label>Access token<input v-model="personal.access_token" type="password" :required="!settings.personal_account" :placeholder="settings.personal_account ? 'Leave blank to keep existing token' : 'Permanent system-user token'"></label><label>Graph version<input v-model="personal.graph_version" required></label><div class="form-actions"><button v-if="settings.personal_account" type="button" class="button danger" @click="disconnect('personal')">Disconnect</button><button class="button primary" :disabled="saving === 'personal'">{{ saving === 'personal' ? 'Saving…' : 'Save personal account' }}</button></div></form>
      <form class="panel whatsapp-account-card" @submit.prevent="save('company')"><header><Building2 /><div><h2>Company fallback account</h2><p>Used when a team member has no personal account.</p></div></header><template v-if="canManageCompany"><label>Display name<input v-model="company.display_name" required maxlength="120"></label><label>Phone number ID<input v-model="company.phone_number_id" required maxlength="80"></label><label>Business account ID<input v-model="company.business_account_id" maxlength="80"></label><label>Access token<input v-model="company.access_token" type="password" :required="!settings.company_account" :placeholder="settings.company_account ? 'Leave blank to keep existing token' : 'Permanent system-user token'"></label><label>Graph version<input v-model="company.graph_version" required></label><div class="form-actions"><button v-if="settings.company_account" type="button" class="button danger" @click="disconnect('company')">Disconnect</button><button class="button primary" :disabled="saving === 'company'">{{ saving === 'company' ? 'Saving…' : 'Save company account' }}</button></div></template><p v-else class="whatsapp-readonly">Only workspace management can change the company fallback. You can still connect your own account.</p></form></section>
      <section class="panel whatsapp-template-panel"><header><div><span class="eyebrow">APPROVED TEMPLATES</span><h2>Meta template mappings</h2><p>Approve these in WhatsApp Manager, then keep the exact names and languages aligned here.</p></div><MessageCircle /></header><article v-for="template in settings.templates" :key="template.id" class="whatsapp-template-row"><div><strong>{{ template.name }}</strong><p>{{ template.body }}</p><small>Parameters: {{ template.parameter_keys.join(', ') }}</small></div><label>Meta name<input v-model="template.meta_template_name" :disabled="!canManageCompany"></label><label>Language<input v-model="template.language_code" :disabled="!canManageCompany"></label><button v-if="canManageCompany" class="button secondary" :disabled="saving === `template-${template.id}`" @click="saveTemplate(template)">Save mapping</button></article></section></template>
  </div>
</template>
